// Deno entry: wasm-bindgen's `deno` target instantiates itself on import, reading its .wasm
// next to the module (needs --allow-read for local files or --allow-net for remote ones).
import { bind } from "./common.js";
import type { WasmApi } from "./types.js";

export * from "./common.js";

export const { openStore, loadWasm } = bind(async (simd) => {
  // @ts-ignore the glue is generated by wasm-bindgen into dist/wasm before this file is used
  const glue: WasmApi = await (simd ? import("./wasm/deno/simd/warm_wasm.js") : import("./wasm/deno/scalar/warm_wasm.js"));
  return glue;
});
